// exports.getProdById = async (req, res, next) => {
//   try {
//     const user = await productsService.findById(req.params.id);
//     if (user) {
//       res.json(user);
//     } else {
//       res.status(404).json({ message: 'Producto no encontrado' });
//     }
//   } catch (error) {
//     next(error);
//   }
