import jwt from 'jsonwebtoken';
import UserService from './loginServices';
import { config } from '../../config';

const JWT_SECRET = config.token_key;
const userService = new UserService();

export const login = async (req, res) => {
  const { username, password } = req.body;

  try {
    // Llamar al servicio para validar las credenciales del usuario
    const users = await userService.findByCredentials(username, password);

    // Verificar si no se encontró el usuario o si hay un error
    if (!users || users.length === 0 || users[0].errorMessage) {
      return res.status(401).json({ message: users[0]?.errorMessage || 'Credenciales inválidas' });
    }

    // Extraer el primer elemento del array
    const user = users[0];

    // Verificar el contenido del objeto `user`
    console.log("Datos del usuario recuperados:", user);

    // Asegurarse de que `user` tenga los campos esperados
    const { id_usuario, nombre, nombre_rol } = user;

    if (!id_usuario || !nombre || !nombre_rol) {
      return res.status(400).json({ message: 'Datos del usuario incompletos' });
    }

    // Generar el token JWT con los datos del usuario
    const token = jwt.sign(
      { id: id_usuario, username: nombre, role: nombre_rol }, 
      JWT_SECRET, 
      { expiresIn: '1h' }
    );

    console.log("Token generado correctamente:", token);

    // Enviar el token como respuesta
    return res.json({ token });
  } catch (error) {
    console.error("Error en el servidor:", error); // Agregar logs en caso de error
    return res.status(500).json({ message: 'Error en el servidor' });
  }
};

