// src/services/UserService.js
import { pool } from '../../config/db.js';

class UserService {

  async findByCredentials(usernameInput, passwordInput) {
    const [rows] = await pool.query('CALL validateUserCredentials(?, ?)', [usernameInput, passwordInput]);
    return rows[0]; // Retorna la información del usuario o un mensaje de error
  }

}

export default UserService;

